import sys
from collections import defaultdict, deque

def main():
    import sys
    input = sys.stdin.read().split()
    index = 0
    T = int(input[index])
    index += 1
    results = []
    for _ in range(T):
        n = int(input[index])
        index += 1
        edges = [tuple(map(int, input[i:i+2])) for i in range(index, index + n - 1)]
        index += n - 1
        colors = input[index]
        index += 1
        graph = defaultdict(list)
        for v, u in edges:
            graph[v].append(u)
            graph[u].append(v)
        degree = {v: len(graph[v]) for v in range(1, n + 1)}
        leafs = deque([v for v in degree if degree[v] == 1])
        while leafs:
            v = leafs.popleft()
            for u in graph[v]:
                degree[u] -= 1
                if degree[u] == 1:
                    leafs.append(u)
        if len(degree) < 3:
            results.append("Draw")
            continue
        white_neighbors = {v: sum(colors[u-1] == 'W' for u in graph[v]) for v in degree}
        if any(white_neighbors[v] >= 2 for v in degree):
            results.append("White")
        else:
            odd_degree = sum(degree[v] % 2 for v in degree)
            if odd_degree >= 3:
                results.append("White")
            elif odd_degree == 1:
                results.append("Black")
            else:
                results.append("Draw")
    print("\n".join(results))

main()
